def test_long_prefill_virtual_batches_exceed_request_count():
    """A long local-attention prefill expands one request into many batches."""
    block_size = 16
    common_attn_metadata = create_common_attn_metadata(
        BatchSpec(query_lens=[34_000], seq_lens=[34_000]),
        block_size,
        torch.device(f"{DEVICE_TYPE}:0"),
    )

    result, _ = make_local_attention_virtual_batches(
        8192, common_attn_metadata, block_size
    )

    assert len(result.seq_lens_cpu) == 5
    assert result.block_table_tensor.shape == (5, 512)
